private func explorerSearch(_ query: String) throws {
        try openExplorer()
        try click("a11y_explorer_components", region: "a11y-circuit-list")
        let search = try revealExplorerSearch()
        try replaceEditorText(search, with: query)
        finishKeyboardEntry()
    }

    private func explorerSearchGeometry(region: CGRect, window: CGRect, inputFrames: [CGRect])
        -> (viewport: CGRect, start: CGPoint, end: CGPoint)? {
        func finite(_ frame: CGRect) -> Bool {
            [frame.origin.x, frame.origin.y, frame.size.width, frame.size.height].allSatisfy { $0.isFinite } &&
                frame.size.width > 0 && frame.size.height > 0
        }
        guard finite(region), finite(window) else { return nil }
        var viewport = region.intersection(window)
        for input in inputFrames {
            guard [input.origin.x, input.origin.y, input.size.width, input.size.height].allSatisfy({ $0.isFinite }),
                  input.size.width >= 0 && input.size.height >= 0 else { return nil }
            if input.size.width == 0 || input.size.height == 0 { continue }
            let obstacle = input.intersection(window)
            if !obstacle.isNull && obstacle.intersects(viewport) {
                viewport = viewport.intersection(CGRect(x: window.minX, y: window.minY,
                    width: window.width, height: max(0, obstacle.minY - window.minY)))
            }
        }
        guard finite(viewport), viewport.width >= 48, viewport.height >= 48 else { return nil }
        let distance = min(CGFloat(96), viewport.height / 4)
        return (viewport, CGPoint(x: viewport.midX, y: viewport.midY - distance / 2),
                CGPoint(x: viewport.midX, y: viewport.midY + distance / 2))
    }

    private func revealExplorerSearch() throws -> XCUIElement {
        let names = try values("a11y_explorer_search")
        for attempt in 0...12 {
            let sheet = identified("editor-tool-sheet")
            let list = identified("a11y-circuit-list")
            guard sheet.exists && list.exists else {
                attach(app.debugDescription, name: "editor-search-missing-container")
                screenshot("editor-search-missing-container")
                XCTFail("The Explorer sheet and list must remain present while revealing Search")
                throw HarnessFailure.missingControl
            }
            var inputFrames = app.keyboards.allElementsBoundByIndex.filter { $0.exists }.map(\.frame)
            for identifier in ["inputView", "SystemInputAssistantView"] {
                let input = identified(identifier)
                if input.exists { inputFrames.append(input.frame) }
            }
            guard let geometry = explorerSearchGeometry(region: list.frame, window: app.frame,
                                                        inputFrames: inputFrames) else {
                attach(app.debugDescription, name: "editor-search-covered-viewport")
                screenshot("editor-search-covered-viewport")
                XCTFail("The Explorer Search needs an observed usable viewport outside native input surfaces")
                throw HarnessFailure.missingControl
            }
            let fields = (app.textViews.matching(identifier: "a11y-circuit-search").allElementsBoundByIndex +
                          app.textFields.matching(identifier: "a11y-circuit-search").allElementsBoundByIndex)
                .filter { $0.exists }
            guard fields.count <= 1 else {
                XCTFail("The tagged Explorer Search must identify one native text control")
                throw HarnessFailure.missingControl
            }
            if let field = fields.first {
                let frame = field.frame
                if [frame.origin.x, frame.origin.y, frame.size.width, frame.size.height].allSatisfy({ $0.isFinite }),
                   frame.size.width >= 48, frame.size.height >= 48, geometry.viewport.contains(frame),
                   names.contains(where: { nativeLabel(field.label, matches: $0) }),
                   field.isEnabled && field.isHittable {
                    checkFrame(field, name: "editor-explorer-search")
                    attach("attempt=\(attempt); field=\(frame); viewport=\(geometry.viewport)",
                           name: "editor-search-before-text-entry")
                    return field
                }
            }
            guard attempt < 12 else { break }
            attach("attempt=\(attempt); viewport=\(geometry.viewport); start=\(geometry.start); end=\(geometry.end)",
                   name: "editor-search-before-backward-scroll")
            let origin = app.coordinate(withNormalizedOffset: .zero)
            let window = app.frame
            origin.withOffset(CGVector(dx: geometry.start.x - window.minX, dy: geometry.start.y - window.minY))
                .press(forDuration: 0.05,
                       thenDragTo: origin.withOffset(CGVector(dx: geometry.end.x - window.minX, dy: geometry.end.y - window.minY)),
                       withVelocity: .slow, thenHoldForDuration: 0.1)
        }
        attach(app.debugDescription, name: "editor-search-not-reachable")
        screenshot("editor-search-not-reachable")
        XCTFail("The Explorer Search did not become fully visible within twelve short backward scrolls")
        throw HarnessFailure.missingControl
    }

